const precip=weatherNow==='rainy'||weatherNow==='snowy';pMat.opacity=lerp(pMat.opacity,precip?.7:0,dt*2);pMat.size=weatherNow==='snowy'?.22:.085;if(precip){for(let i=0;i<particles;i++){pArray[i*3+1]-=dt*(weatherNow==='snowy'?3:36);pArray[i*3]+=dt*(weatherNow==='snowy'?Math.sin(elapsed+i)*.6:2);pArray[i*3+2]+=dt*state.speed;if(pArray[i*3+1]<0){pArray[i*3+1]=65;pArray[i*3]=(Math.random()-.5)*150;}if(pArray[i*3+2]>20)pArray[i*3+2]=-130;}pGeo.attributes.position.needsUpdate=true;}
let cp,look;const bend=roadX(state.distance+55)-base;if(state.cam===0){cp=new T.Vector3(player.position.x+1.5,3.3,8.5);look=new T.Vector3(player.position.x+bend*.16,1.15,-9);}else if(state.cam===1){cp=new T.Vector3(player.position.x, state.ride==='car'?1.85:2.15,-.1);look=new T.Vector3(bend+2.9,1.6,-55);}else{cp=new T.Vector3(player.position.x-10,5.8,10);look=new T.Vector3(bend*.15,0,-16);}camera.position.lerp(cp,1-Math.exp(-dt*3));camera.lookAt(look);const fov=state.cam===1?65+state.speed*.25:50+state.speed*.16;camera.fov=lerp(camera.fov,fov,dt*2);camera.updateProjectionMatrix();
