function pause(){if(!state.started)return;state.paused=!state.paused;$('#pause').textContent=state.paused?'▶':'Ⅱ';toast(state.paused?'Take a breath. The road can wait.':'And away we go.');}
$('#start').onclick=()=>{document.body.classList.remove('home');state.started=true;$('#intro').classList.add('gone');$('#panel').classList.add('closed');toast('Nowhere to be. Just enjoy the journey.');};$('#settings').onclick=()=>$('#panel').classList.toggle('closed');$('#pause').onclick=pause;$('#camera').onclick=()=>{state.cam=(state.cam+1)%3;toast(['Chase camera','Driver’s view','Scenic camera'][state.cam]);};$('#speed').oninput=e=>state.target=+e.target.value;$('#time').oninput=e=>{state.time=+e.target.value;state.autoTime=false;$('#autotime').checked=false;};$('#autotime').onchange=e=>state.autoTime=e.target.checked;segmented('#biome',v=>{state.biome=['fields','desert','mountain','town','snow'].includes(v)?v:'auto';rebuild();regionNow='';if(state.weather==='auto')weatherNow=pickWeather();});
function segmented(id,fn){$(id).onclick=e=>{const b=e.target.closest('button');if(!b)return;$(id).querySelectorAll('button').forEach(el=>el.classList.toggle('active',el===b));fn(b.dataset.value);};}
segmented('#weather',v=>{state.weather=v;weatherNow=v==='auto'?pickWeather():v;toast(v==='auto'?'The forecast follows your journey.':'A little '+v+' weather.');});segmented('#modes',v=>{state.mode=v;toast(v==='manual'?'Use W A S D or the arrow keys to drive.':'Settle in. Cruise control is on.');});segmented('#rides',v=>{state.ride=v;scene.remove(player);player.traverse(o=>{if(o.isMesh)o.geometry.dispose();});player=makeVehicle(v);scene.add(player);state.target=v==='cycle'?24:v==='bike'?75:65;$('#speed').value=state.target;toast({car:'Your open-top escape.',bike:'Two wheels. An open road.',cycle:'Slow down and hear the world.'}[v]);});
$('#fullscreen').onclick=async()=>{try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen();}catch{toast('Fullscreen is unavailable in this view.');}};
$('#sound').onclick=async()=>{try{if(!audio){audio=new AudioContext();engine=audio.createOscillator();engine.type='sawtooth';gain=audio.createGain();gain.gain.value=0;const filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=180;engine.connect(filter).connect(gain).connect(audio.destination);engine.start();const buffer=audio.createBuffer(1,audio.sampleRate*2,audio.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;const noise=audio.createBufferSource();noise.buffer=buffer;noise.loop=true;const nf=audio.createBiquadFilter();nf.type='lowpass';nf.frequency.value=650;noiseGain=audio.createGain();noiseGain.gain.value=0;noise.connect(nf).connect(noiseGain).connect(audio.destination);noise.start();}await audio.resume();state.sound=!state.sound;$('#sound small').textContent=state.sound?'SOUND ON':'SOUND OFF';}catch{toast('Audio is unavailable in this browser.');}};
window.addEventListener('keydown',e=>{if(['INPUT','SELECT'].includes(document.activeElement.tagName))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key]=true;if(e.repeat)return;if(e.key===' ')pause();if(e.key.toLowerCase()==='c')$('#camera').click();});window.addEventListener('keyup',e=>keys[e.key]=false);window.addEventListener('blur',()=>{Object.keys(keys).forEach(k=>keys[k]=false);});document.querySelectorAll('#touch button').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[b.dataset.key]=true;if(state.mode==='cruise'){state.mode='manual';document.querySelectorAll('#modes button').forEach(x=>x.classList.toggle('active',x.dataset.value==='manual'));}};b.onpointerup=b.onpointercancel=()=>keys[b.dataset.key]=false;});window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});
